    ReadingText(id: "en-read-doctor-advice", languageID: "en", title: "The doctor's advice", level: "A2", topic: "health",
        text: "Patient information sheet — Tiredness. Are you sleeping badly? Many office workers feel tired all week. Our doctors say: You shouldn't drink coffee after four o'clock. You should go to bed at the same time every night — your body loves routine. You mustn't use screens in bed: the light tells your brain it's daytime. You don't have to sleep eight hours exactly — seven can be enough if it's good sleep. Exercise helps, but not just before bed: a walk at lunchtime is better than a run at ten at night. If you're still tired after two weeks of good habits, you should book an appointment. Sleep well!",
        questions: [
                            Exercise(id: "en-read-doctor-advice-q1", kind: "choice", prompt: "When shouldn't you drink coffee?", options: ["After four o'clock", "In the morning", "Before lunch", "With food"], answers: ["After four o'clock"], explain: "You shouldn't drink coffee after four o'clock."),
                            Exercise(id: "en-read-doctor-advice-q2", kind: "written", prompt: "What mustn't you do in bed?", options: [], answers: ["use screens", "use screens in bed", "look at screens"], explain: "You mustn't use screens in bed."),
                            Exercise(id: "en-read-doctor-advice-q3", kind: "choice", prompt: "How much sleep do you have to get?", options: ["Seven can be enough", "Exactly eight hours", "Nine hours", "Ten hours"], answers: ["Seven can be enough"], explain: "You don't have to sleep eight hours — seven is fine if it's good sleep."),
                            Exercise(id: "en-read-doctor-advice-q4", kind: "choice", prompt: "When is exercise better?", options: ["A walk at lunchtime", "A run at ten at night", "Never", "Just before bed"], answers: ["A walk at lunchtime"], explain: "A walk at lunchtime is better than a run at night."),
                            Exercise(id: "en-read-doctor-advice-q5", kind: "written", prompt: "What should you do if good habits don't work after two weeks?", options: [], answers: ["book an appointment", "book a doctors appointment", "see a doctor", "you should book an appointment"], explain: "You should book an appointment.")], skills: ["reading:detail", "grammar:modal-should", "grammar:modal-must-have-to", "vocab:health"]),
    ReadingText(id: "en-read-complaint-email", languageID: "en", title: "A short complaint email", level: "A2", topic: "problems",
        text: "Subject: Order 4492 — wrong size. Dear Customer Service, I ordered a winter jacket (size M, order 4492) on 3 October, and it arrived on Thursday. Unfortunately, you sent size S instead of M. I checked the box and the label — both say S. I like the jacket and I want to keep it, so I would like to exchange it for the correct size. Should I send the small one back first, or do you send the new one and collect the other? The return service near me is only open in the mornings, so a home collection would be easier. I have to say the delivery was very fast — that part was perfect! I look forward to your reply. Best regards, Daniel Ortiz (customer since 2021)",
        questions: [
                            Exercise(id: "en-read-complaint-email-q1", kind: "choice", prompt: "What was wrong with the order?", options: ["The size", "The colour", "The price", "The delivery day"], answers: ["The size"], explain: "They sent size S instead of M."),
                            Exercise(id: "en-read-complaint-email-q2", kind: "choice", prompt: "What does Daniel want?", options: ["To exchange it for the correct size", "His money back", "A discount", "A different jacket"], answers: ["To exchange it for the correct size"], explain: "He likes the jacket and wants to exchange it."),
