                            Exercise(id: "en-read-complaint-email-q4", kind: "choice", prompt: "What was perfect, according to Daniel?", options: ["The delivery", "The price", "The box", "The label"], answers: ["The delivery"], explain: "He has to admit: the delivery was very fast."),
