    ReadingText(id: "en-read-hotel-review", languageID: "en", title: "A review: The Glass House Hotel", level: "B1", topic: "travel",
        text: "★★★☆☆ The Glass House Hotel looks spectacular online, and to be fair, the reality is close: the glass roof over the lobby is stunning, and our room, which faced the harbour, had the best view of the week. However, several things annoyed me. Although the website promises 'quiet rooms', ours was above the bar, and the music went on until one in the morning. The breakfast, which is served until ten, ran out of almost everything by nine on both mornings. The staff, who were genuinely kind, tried to help — they moved us on the second night and offered free coffee. Would I return? If they soundproof the bar, yes. If not, I'll pay ten euros more for the hotel next door, which, according to friends, is quieter and includes breakfast.",
        questions: [
                            Exercise(id: "en-read-hotel-review-q1", kind: "choice", prompt: "What did the reviewer love about the room?", options: ["The view of the harbour", "The glass roof", "The bar downstairs", "The breakfast"], answers: ["The view of the harbour"], explain: "Their room faced the harbour and had the best view of the week."),
                            Exercise(id: "en-read-hotel-review-q2", kind: "written", prompt: "Why didn't they sleep well?", options: [], answers: ["the music from the bar", "the bar music", "music until one in the morning"], explain: "The room was above the bar; music until one."),
                            Exercise(id: "en-read-hotel-review-q3", kind: "choice", prompt: "What did the staff do?", options: ["They moved them and offered free coffee", "Nothing", "They refunded the night", "They closed the bar"], answers: ["They moved them and offered free coffee"], explain: "The staff, who were genuinely kind, moved them on the second night."),
                            Exercise(id: "en-read-hotel-review-q4", kind: "choice", prompt: "What will make the reviewer return?", options: ["Soundproofing the bar", "A discount", "A better view", "An earlier breakfast"], answers: ["Soundproofing the bar"], explain: "If they soundproof the bar, yes."),
                            Exercise(id: "en-read-hotel-review-q5", kind: "written", prompt: "According to friends, what is the hotel next door like?", options: [], answers: ["quieter and includes breakfast", "quieter", "quieter and with breakfast included"], explain: "Quieter and includes breakfast.")], skills: ["reading:inference", "grammar:relative-clauses", "grammar:first-conditional", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "en-read-remote-work", languageID: "en", title: "Is remote work working?", level: "B1", topic: "work",
        text: "Five years ago, most offices insisted that great work needed a shared room. Today, that idea is under review. Companies which moved to hybrid schedules report fewer sick days and lower costs; employees save hours of commuting every week, and many say they are more productive at home. However, the picture is not simple. New employees who have never met their teams in person often feel invisible, and creative work — the kind that grows from accidental corridor conversations — seems harder online. Although younger workers usually prefer flexibility, some admit that home offices blur the line between life and work until answering emails at midnight feels normal again. Perhaps the honest answer is that remote work works when the work is remote-shaped: independent, measured by results, written down. For everything else, the corridor still has value.",
        questions: [
                            Exercise(id: "en-read-remote-work-q1", kind: "choice", prompt: "What do companies with hybrid schedules report?", options: ["Fewer sick days and lower costs", "Higher costs", "Worse productivity", "Nothing"], answers: ["Fewer sick days and lower costs"], explain: "They report fewer sick days and lower costs."),
                            Exercise(id: "en-read-remote-work-q2", kind: "written", prompt: "Who often feels invisible?", options: [], answers: ["new employees", "new employees who have never met their teams", "new people"], explain: "New employees who have never met their teams in person."),
                            Exercise(id: "en-read-remote-work-q3", kind: "choice", prompt: "What kind of work seems harder online?", options: ["Creative work", "Administrative work", "Written work", "Independent work"], answers: ["Creative work"], explain: "Work that grows from corridor conversations seems harder online."),
                            Exercise(id: "en-read-remote-work-q4", kind: "written", prompt: "What negative habit can return with home offices?", options: [], answers: ["answering emails at midnight", "answering emails late at night", "working at midnight"], explain: "Answering emails at midnight can feel normal again."),
                            Exercise(id: "en-read-remote-work-q5", kind: "choice", prompt: "When does remote work work, according to the article?", options: ["When the work is remote-shaped", "Never", "Always", "Only for managers"], answers: ["When the work is remote-shaped"], explain: "Independent, measured by results, written down.")], skills: ["reading:inference", "grammar:relative-clauses", "grammar:connectors", "grammar:present-perfect", "vocab:work"]),
    ReadingText(id: "en-read-missing-keys", languageID: "en", title: "The missing keys", level: "B1", topic: "stories",
        text: "Marta was making coffee when she realised the flat was silent — the specific, heavy silence of a missing object. Her keys, which always lived in the blue bowl by the door, were gone. She looked in her coat, in yesterday's bag, under the sofa where small things liked to disappear. Nothing. While she was searching, her phone buzzed: a message from Diego, her downstairs neighbour. 'Are you missing something shiny? A little thief brought me a present.' His cat, Luna, had a habit of collecting small metal objects, and although Marta had never caught her in the act, the evidence was now clear: three keys, a bottle opener and last winter's missing earring. Marta went downstairs, laughed until her sides hurt, and installed a hook high on the wall. The bowl stayed empty from that day; Luna, however, kept bringing gifts.",
        questions: [
                            Exercise(id: "en-read-missing-keys-q1", kind: "choice", prompt: "What was Marta doing when she noticed the silence?", options: ["Making coffee", "Searching the sofa", "Reading a message", "Going downstairs"], answers: ["Making coffee"], explain: "She was making coffee when she realised."),
                            Exercise(id: "en-read-missing-keys-q2", kind: "written", prompt: "Where did the keys usually live?", options: [], answers: ["in the blue bowl", "the blue bowl by the door", "the blue bowl"], explain: "They always lived in the blue bowl by the door."),
                            Exercise(id: "en-read-missing-keys-q3", kind: "choice", prompt: "Who took the keys?", options: ["Diego's cat", "Diego", "A neighbour", "Nobody knows"], answers: ["Diego's cat"], explain: "Luna, the downstairs cat, collected small metal objects."),
                            Exercise(id: "en-read-missing-keys-q4", kind: "written", prompt: "Name one other thing Luna had taken.", options: [], answers: ["a bottle opener", "an earring", "last winter's missing earring", "three keys"], explain: "Three keys, a bottle opener and an earring."),
                            Exercise(id: "en-read-missing-keys-q5", kind: "choice", prompt: "What was Marta's solution?", options: ["A hook high on the wall", "A new bowl", "A locked box", "She locked Luna out"], answers: ["A hook high on the wall"], explain: "She installed a hook high on the wall."),
                            Exercise(id: "en-read-missing-keys-q6", kind: "choice", prompt: "Did Luna stop bringing gifts?", options: ["No — she kept bringing them", "Yes, immediately", "Yes, after a week", "The text doesn't say"], answers: ["No — she kept bringing them"], explain: "Luna, however, kept bringing gifts.")], skills: ["reading:detail", "grammar:past-continuous", "grammar:relative-clauses", "grammar:connectors", "function:tell-a-story"]),
    ReadingText(id: "en-read-meetup-email", languageID: "en", title: "Planning the alumni meetup", level: "B1", topic: "plans",
        text: "Subject: Alumni meetup — your vote needed! Hi everyone, Great news: 34 of you answered the survey, so we're finally organising the spring meetup. The Terraza del Río, which most of you recommended, has availability on 14 or 21 June. If we choose the 14th, we'll have the terrace to ourselves but we'll have to finish by midnight. If we choose the 21st, it's shared with another group, although the music usually stops earlier. Several of you asked about a pre-dinner walk — if enough people arrive by 19:30, we'll do the river route first (about 40 minutes, flat and easy). Please vote by Friday. If fewer than twenty people vote, we'll postpone to September and I'll donate the deposit to the class fund! Looking forward to it, Bea",
        questions: [
                            Exercise(id: "en-read-meetup-email-q1", kind: "choice", prompt: "Which venue did most people recommend?", options: ["Terraza del Río", "The class fund", "The river route", "A shared hall"], answers: ["Terraza del Río"], explain: "The Terraza del Río, which most of you recommended."),
                            Exercise(id: "en-read-meetup-email-q2", kind: "choice", prompt: "What is the downside of the 14th?", options: ["They must finish by midnight", "Another group shares it", "No terrace", "It's in September"], answers: ["They must finish by midnight"], explain: "On the 14th they have the terrace to themselves but finish by midnight."),
                            Exercise(id: "en-read-meetup-email-q3", kind: "written", prompt: "What do they plan to do if enough people arrive by 19:30?", options: [], answers: ["the river route", "do the river route first", "walk the river route"], explain: "They'll do the river route first."),
                            Exercise(id: "en-read-meetup-email-q4", kind: "choice", prompt: "What happens if fewer than twenty people vote?", options: ["The meetup moves to September", "Bea chooses the date", "The venue decides", "Nothing"], answers: ["The meetup moves to September"], explain: "They'll postpone to September and donate the deposit."),
                            Exercise(id: "en-read-meetup-email-q5", kind: "written", prompt: "How long is the river walk?", options: [], answers: ["about 40 minutes", "40 minutes", "forty minutes"], explain: "About 40 minutes, flat and easy.")], skills: ["reading:detail", "grammar:first-conditional", "grammar:connectors", "writing:email"]),
    ReadingText(id: "en-read-ai-emails-debate", languageID: "en", title: "Should AI write our emails?", level: "B2", topic: "work",
        text: "Last quarter, our company quietly enabled an AI assistant for all internal email. The results were measured, and they are worth reporting precisely. Response times improved by roughly a third, and — perhaps surprisingly — politeness increased: messages drafted by the assistant contain fewer blunt openings and more complete sentences. However, two problems are emerging. First, readers are starting to discount the politeness; when everyone sounds courteous, courtesy stops carrying information. Second, and more seriously, responsibility is blurring. When a wrong figure was sent to a client last month, three people said some version of 'the assistant wrote it.' The tool was not to blame, of course — the signature was. My position is therefore narrow but firm: let the assistant draft, but the name at the bottom owns every word. We are testing a one-line disclosure at the end of assisted emails, and if trust metrics hold, we will keep it. If they do not, we will rethink — in our own words.",
        questions: [
                            Exercise(id: "en-read-ai-emails-debate-q1", kind: "written", prompt: "By how much did response times improve?", options: [], answers: ["roughly a third", "about a third", "a third"], explain: "Response times improved by roughly a third."),
                            Exercise(id: "en-read-ai-emails-debate-q2", kind: "choice", prompt: "What surprising effect did the assistant have?", options: ["Politeness increased", "Emails got shorter", "People wrote less", "Costs fell"], answers: ["Politeness increased"], explain: "Messages contained fewer blunt openings and more complete sentences."),
                            Exercise(id: "en-read-ai-emails-debate-q3", kind: "choice", prompt: "What happens when everyone sounds courteous?", options: ["Courtesy stops carrying information", "Emails get longer", "Nothing", "People write more"], answers: ["Courtesy stops carrying information"], explain: "Discounted politeness carries less meaning."),
                            Exercise(id: "en-read-ai-emails-debate-q4", kind: "choice", prompt: "What is the author's firm position?", options: ["The signature owns every word", "Ban the assistant", "AI should write everything", "No disclosure needed"], answers: ["The signature owns every word"], explain: "Let it draft, but the name at the bottom owns every word."),
                            Exercise(id: "en-read-ai-emails-debate-q5", kind: "written", prompt: "What will they do if trust metrics do not hold?", options: [], answers: ["rethink", "they will rethink in their own words", "rethink the policy"], explain: "If they do not, they will rethink — in their own words.")], skills: ["reading:inference", "grammar:passive-intro", "grammar:connectors", "grammar:first-conditional", "writing:argument"]),
    ReadingText(id: "en-read-market-report", languageID: "en", title: "Quarter in brief: the coffee market", level: "B2", topic: "business",
        text: "Summary for internal circulation — Q3. Prices rose considerably in the first half of the quarter, driven by weather rather than demand: the frost in July affected the two largest producing regions, which together account for roughly 55% of exports. Demand, by contrast, was flat. Supermarket own-brand lines were the least affected, arguably because their contracts are fixed annually; speciality roasters, which buy on the spot market, reported increases of up to forty per cent. It is widely believed that small cafés absorb such increases poorly, and our survey offers some support: 62% said they would rather reduce opening hours than raise the price of an espresso. Looking ahead, futures suggest a partial correction by December, although this depends on rainfall in August. We therefore recommend hedging half of Q4 volume now and reviewing the remainder in October. As ever, this report is a snapshot, not a guarantee.",
        questions: [
                            Exercise(id: "en-read-market-report-q1", kind: "choice", prompt: "What drove prices up?", options: ["Weather", "Demand", "New cafés", "Export taxes"], answers: ["Weather"], explain: "The July frost, not demand — demand was flat."),
                            Exercise(id: "en-read-market-report-q2", kind: "written", prompt: "How much of exports do the two largest regions account for?", options: [], answers: ["roughly 55%", "55%", "about 55 percent"], explain: "Roughly 55% of exports."),
                            Exercise(id: "en-read-market-report-q3", kind: "choice", prompt: "Which buyers were least affected?", options: ["Supermarket own brands", "Speciality roasters", "Small cafés", "Futures traders"], answers: ["Supermarket own brands"], explain: "Arguably because their contracts are fixed annually."),
                            Exercise(id: "en-read-market-report-q4", kind: "written", prompt: "What would 62% of small cafés rather do?", options: [], answers: ["Reduce opening hours"], explain: "Rather than raise the price of an espresso."),
                            Exercise(id: "en-read-market-report-q5", kind: "choice", prompt: "What does the report recommend for Q4?", options: ["Hedging half the volume now", "Waiting until December", "Buying nothing", "Raising prices by 40%"], answers: ["Hedging half the volume now"], explain: "Hedge half now, review the rest in October.")], skills: ["reading:inference", "grammar:passive-intro", "grammar:relative-clauses", "grammar:connectors", "function:express-opinion"]),
    ReadingText(id: "en-read-op-ed-cities", languageID: "en", title: "Op-ed: the fifteen-minute fantasy", level: "C1", topic: "town",
        text: "The fifteen-minute city is, depending on who you ask, the future of urban life or a conspiracy with better branding. Strip away the noise, however, and the concept is almost disappointingly modest: housing, work, school and groceries within a short walk. That this modesty has been received as tyranny says less about urbanism than about the era in which it landed. Critics are right about one thing, though — proximity is a luxury good. The neighbourhoods that already deliver it are the most expensive in every city that measures, and a plan that paints a café on a map does not lower the rent. Arguably, then, the real fifteen-minute policy is not zoning but housing: build where people want to live, and the walk to the bakery takes care of itself. None of this makes the idea wrong. It makes it insufficient — which, in a field allergic to nuance, is already an unpopular position.",
        questions: [
                            Exercise(id: "en-read-op-ed-cities-q1", kind: "choice", prompt: "How does the author characterise the fifteen-minute city concept itself?", options: ["Almost disappointingly modest", "A conspiracy", "The future of urban life", "Tyranny"], answers: ["Almost disappointingly modest"], explain: "Strip away the noise and the concept is almost disappointingly modest."),
                            Exercise(id: "en-read-op-ed-cities-q2", kind: "choice", prompt: "What do critics get right, according to the author?", options: ["Proximity is a luxury good", "Zoning is evil", "Cafés ruin cities", "Nothing"], answers: ["Proximity is a luxury good"], explain: "Critics are right about one thing: the neighbourhoods that deliver it are the most expensive."),
                            Exercise(id: "en-read-op-ed-cities-q3", kind: "written", prompt: "What does the author call the real fifteen-minute policy?", options: [], answers: ["housing", "build where people want to live"], explain: "Not zoning but housing: build where people want to live."),
                            Exercise(id: "en-read-op-ed-cities-q4", kind: "written", prompt: "What is the author's final judgement of the idea?", options: [], answers: ["insufficient, not wrong", "it makes the idea insufficient"], explain: "It makes the idea insufficient — which is already unpopular."),
                            Exercise(id: "en-read-op-ed-cities-q5", kind: "choice", prompt: "What does 'a field allergic to nuance' imply?", options: ["Urbanism debates reject subtle positions", "Urbanists have allergies", "Cities cause allergies", "Nuance is common"], answers: ["Urbanism debates reject subtle positions"], explain: "Allergic to nuance = the field dislikes intermediate positions.")], skills: ["reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "vocab:town"]),
    ReadingText(id: "en-read-policy-memo", languageID: "en", title: "Internal memo: hybrid policy review", level: "C1", topic: "work",
        text: "MEMO — For internal circulation. Re: Hybrid working policy, phase two review. 1. Purpose. This memo summarises the findings of the phase-two review and sets out recommendations for the coming financial year. 2. Findings. Office attendance has averaged 2.3 days per week against a target of three, a shortfall attributable primarily to Wednesdays, which function in practice as a de facto remote day. Cross-team collaboration, as measured by shared project hours, has declined 12% year on year; within-team collaboration is unchanged. Exit interviews cite flexibility as the single most valued benefit (cited by 71% of leavers, compared with 34% for compensation). 3. Recommendations. It is recommended that: (a) Wednesday be designated a full on-site day with team-led programming; (b) the target be revised to an average, not a minimum; (c) the policy be reviewed again in twelve months. 4. Caveat. Attendance data was collected via badge swipes and may undercount presence in non-badged areas.",
        questions: [
                            Exercise(id: "en-read-policy-memo-q1", kind: "written", prompt: "What is the average office attendance against the target?", options: [], answers: ["2.3 days per week against a target of three", "2.3 days", "2,3 days"], explain: "2.3 days per week against a target of three."),
                            Exercise(id: "en-read-policy-memo-q2", kind: "choice", prompt: "What is the primary cause of the shortfall?", options: ["Wednesdays functioning as a remote day", "Bad weather", "The badge system", "Low pay"], answers: ["Wednesdays functioning as a remote day"], explain: "A shortfall attributable primarily to Wednesdays."),
                            Exercise(id: "en-read-policy-memo-q3", kind: "choice", prompt: "What do exit interviews cite as the most valued benefit?", options: ["Flexibility", "Compensation", "Laptops", "Wednesdays"], answers: ["Flexibility"], explain: "Flexibility: 71% of leavers, compared with 34% for compensation."),
                            Exercise(id: "en-read-policy-memo-q4", kind: "written", prompt: "Name one of the three recommendations.", options: [], answers: ["wednesday be designated a full on-site day", "the target be revised to an average", "the policy be reviewed again in twelve months"], explain: "Any of (a), (b) or (c)."),
                            Exercise(id: "en-read-policy-memo-q5", kind: "choice", prompt: "What caveat does the memo admit?", options: ["Badge data may undercount presence", "The survey was fake", "There is no data", "The target was met"], answers: ["Badge data may undercount presence"], explain: "Badge swipes miss non-badged areas.")], skills: ["reading:scan", "reading:detail", "grammar:passive-intro", "vocab:work", "writing:email"]),
    ReadingText(id: "en-read-neighbourhood-blog", languageID: "en", title: "Neighbourhood notes: Maple Street", level: "A1", topic: "town",
        text: "Welcome to Maple Street! Our street is small but friendly. There is a bakery on the corner — the bread is very good. There are two schools and a small park with ten trees. There isn't a cinema, but the library is open on Saturdays. The chemist's is next to the park. Everything is near the bus stop. Our neighbours are friendly and quiet. On Saturdays there is a small market with fruit and flowers. Come and visit!",
        questions: [
                            Exercise(id: "en-read-neighbourhood-blog-q1", kind: "choice", prompt: "What is on the corner?", options: ["A bakery", "A cinema", "A school", "A market"], answers: ["A bakery"], explain: "There is a bakery on the corner."),
                            Exercise(id: "en-read-neighbourhood-blog-q2", kind: "written", prompt: "How many trees are in the park?", options: [], answers: ["ten", "10"], explain: "A small park with ten trees."),
                            Exercise(id: "en-read-neighbourhood-blog-q3", kind: "choice", prompt: "When is the library open?", options: ["On Saturdays", "Every day", "Never", "On Sundays"], answers: ["On Saturdays"], explain: "The library is open on Saturdays."),
                            Exercise(id: "en-read-neighbourhood-blog-q4", kind: "choice", prompt: "Where is the chemist's?", options: ["Next to the park", "On the corner", "Near the school", "Far away"], answers: ["Next to the park"], explain: "The chemist's is next to the park."),
                            Exercise(id: "en-read-neighbourhood-blog-q5", kind: "choice", prompt: "What is there on Saturdays?", options: ["A small market", "A cinema", "A party", "Nothing"], answers: ["A small market"], explain: "Fruit and flowers — the Saturday market.")], skills: ["vocab:town", "grammar:there-is-are", "reading:detail", "function:ask-simple-questions"]),
    ReadingText(id: "en-read-tuscany-note", languageID: "en", title: "A very short travel story", level: "B1", topic: "travel",
        text: "The lock wouldn't turn. That was the first sign. My Airbnb host had sent four codes for one door, and none of them worked. It was 30 degrees, my phone had 4% battery, and a man with a dog was watching me from a window. I typed a message to the host: 'I'm outside, the codes don't work.' Three dots. Nothing. Ten minutes later the dog man opened the door downstairs. 'You must be the Tuscany guest,' he said, in perfect English. 'My daughter manages the flat. Come up, have some water.' By the time I got inside, we had laughed about the codes twice, and he had given me two plums from his tree. Some arrivals are better than the photos.",
        questions: [
                            Exercise(id: "en-read-tuscany-note-q1", kind: "choice", prompt: "What is the first sign of trouble?", options: ["The lock wouldn't turn", "The host's message", "The dog", "The heat"], answers: ["The lock wouldn't turn"], explain: "Open in the middle: the lock wouldn't turn."),
                            Exercise(id: "en-read-tuscany-note-q2", kind: "written", prompt: "How many codes did the host send?", options: [], answers: ["four", "4"], explain: "Four codes for one door."),
                            Exercise(id: "en-read-tuscany-note-q3", kind: "choice", prompt: "What was the phone's battery?", options: ["4%", "40%", "Full", "Dead"], answers: ["4%"], explain: "My phone had 4% battery."),
                            Exercise(id: "en-read-tuscany-note-q4", kind: "written", prompt: "What did the dog man give the guest?", options: [], answers: ["two plums", "plums", "some plums"], explain: "Two plums from his tree."),
                            Exercise(id: "en-read-tuscany-note-q5", kind: "choice", prompt: "What is the closing thought?", options: ["Some arrivals are better than the photos", "Never use Airbnb", "Tuscany is far", "Dogs are friendly"], answers: ["Some arrivals are better than the photos"], explain: "One line, reflective, light.")], skills: ["reading:inference", "grammar:past-continuous", "function:tell-a-story", "grammar:connectors", "writing:story"]),
    ReadingText(id: "en-read-opinion-ai-art", languageID: "en", title: "Opinion: AI art is still art", level: "B2", topic: "work",
        text: "The argument against AI art is always the same: a machine cannot feel, therefore it cannot create. But this argument proves too much. If feeling is the requirement, then we must also reject photography (the camera does not feel), digital painting (the software does not feel) and, arguably, most commissioned work (the painter does not always feel either). What matters is not the tool but the intention behind it. A person who writes a prompt, curates the output, revises, and presents the result is making choices. Those choices may be good or bad — that is a separate question. But they are choices, and choices are the raw material of art. The real threat is not AI art; it is the flood of mediocre AI art that drowns the genuinely interesting work. The solution is curation, not prohibition.",
        questions: [
                            Exercise(id: "en-read-opinion-ai-art-q1", kind: "choice", prompt: "What is the standard argument against AI art?", options: ["A machine cannot feel, so it cannot create", "AI art is too expensive", "AI art is too fast", "Nobody likes it"], answers: ["A machine cannot feel, so it cannot create"], explain: "A machine cannot feel, therefore it cannot create."),
                            Exercise(id: "en-read-opinion-ai-art-q2", kind: "choice", prompt: "What does the author say the argument proves too much?", options: ["It would also reject photography and digital painting", "It proves AI is bad", "It proves artists are wrong", "Nothing"], answers: ["It would also reject photography and digital painting"], explain: "The camera doesn't feel either."),
                            Exercise(id: "en-read-opinion-ai-art-q3", kind: "written", prompt: "What matters more than the tool?", options: [], answers: ["the intention behind it"], explain: "What matters is the intention, not the tool."),
                            Exercise(id: "en-read-opinion-ai-art-q4", kind: "written", prompt: "What are the raw material of art?", options: [], answers: ["choices"], explain: "Choices are the raw material of art."),
                            Exercise(id: "en-read-opinion-ai-art-q5", kind: "choice", prompt: "What is the real threat?", options: ["The flood of mediocre AI art", "AI art itself", "Prohibition", "Traditional artists"], answers: ["The flood of mediocre AI art"], explain: "The flood drowns the genuinely interesting work."),
                            Exercise(id: "en-read-opinion-ai-art-q6", kind: "choice", prompt: "What solution does the author propose?", options: ["Curation, not prohibition", "Banning AI art", "More AI art", "Higher prices"], answers: ["Curation, not prohibition"], explain: "Curation, not prohibition.")], skills: ["reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "grammar:passive-intro"]),
    ReadingText(id: "en-read-policy-report", languageID: "en", title: "Policy report: libraries in the digital age", level: "C1", topic: "work",
        text: "1. Scope. This report examines the role of public libraries in municipalities with populations exceeding 50,000, drawing on data from 340 institutions across 12 countries collected between 2022 and 2025. 2. Principal findings. Contrary to widespread assumptions, circulation of physical books has declined by only 8% since 2022, while attendance at non-book events (workshops, language exchanges, coding clubs) has increased by 210% over the same period. Libraries that rebranded as 'community hubs' saw a 34% increase in first-time visitors; those that maintained a traditional focus saw a 14% decrease. It should be noted, however, that the rebranding group also received 40% more funding on average, making causality difficult to establish. 3. Limitations. The data excludes rural libraries and does not distinguish between scheduled and walk-in attendance. 4. Recommendation. Municipalities should fund libraries as social infrastructure rather than as book warehouses, and should commission a follow-up study with better attendance methodology.",
        questions: [
                            Exercise(id: "en-read-policy-report-q1", kind: "choice", prompt: "How much has physical book circulation declined?", options: ["8% since 2022", "80% since 2022", "It has increased", "It has not changed"], answers: ["8% since 2022"], explain: "Contrary to assumptions, only 8% decline."),
                            Exercise(id: "en-read-policy-report-q2", kind: "written", prompt: "By how much have non-book events increased?", options: [], answers: ["210%"], explain: "Attendance at non-book events has increased by 210%."),
                            Exercise(id: "en-read-policy-report-q3", kind: "choice", prompt: "What happened to libraries that rebranded as community hubs?", options: ["34% more first-time visitors", "34% fewer visitors", "No change", "They closed"], answers: ["34% more first-time visitors"], explain: "A 34% increase in first-time visitors."),
                            Exercise(id: "en-read-policy-report-q4", kind: "choice", prompt: "What limitation does the report admit?", options: ["Rebranding libraries received 40% more funding", "The data is fake", "Libraries refused to participate", "No limitation"], answers: ["Rebranding libraries received 40% more funding"], explain: "More funding makes causality difficult to establish."),
                            Exercise(id: "en-read-policy-report-q5", kind: "choice", prompt: "What does the report recommend?", options: ["Fund libraries as social infrastructure", "Close libraries", "Buy more books", "Stop funding"], answers: ["Fund libraries as social infrastructure"], explain: "Fund as social infrastructure, not book warehouses."),
                            Exercise(id: "en-read-policy-report-q6", kind: "written", prompt: "What data does the report exclude?", options: [], answers: ["rural libraries"], explain: "The data excludes rural libraries.")], skills: ["reading:inference", "reading:scan", "grammar:passive-intro", "grammar:connectors", "writing:argument"]),
    ReadingText(id: "es-read-grupo-caminata", languageID: "es", title: "El grupo de caminata", level: "A1", topic: "salud", unitID: "es-foundations-u2",
        text: "Los martes, el barrio organiza una caminata gratis. Empieza a las nueve en la plaza y termina en el río. El grupo es mixto: hay estudiantes, familias y jubilados. Nadie corre; la idea es caminar y hablar. Al final, los que quieren desayunan juntos en un bar del mercado. Marta va desde hace un mes y ya tiene tres amigos nuevos. Dice que es la hora más tranquila de su semana.",
        questions: [
                            Exercise(id: "es-read-grupo-caminata-q1", kind: "choice", prompt: "¿Cuándo es la caminata?", options: ["Los martes", "Los lunes", "Los sábados", "Todos los días"], answers: ["Los martes"], explain: "Los martes, el barrio organiza una caminata gratis."),
                            Exercise(id: "es-read-grupo-caminata-q2", kind: "written", prompt: "¿A qué hora empieza?", options: [], answers: ["a las nueve", "las nueve", "nueve"], explain: "Empieza a las nueve en la plaza."),
                            Exercise(id: "es-read-grupo-caminata-q3", kind: "choice", prompt: "¿Quién va al grupo?", options: ["Estudiantes, familias y jubilados", "Solo estudiantes", "Solo jubilados", "Solo familias"], answers: ["Estudiantes, familias y jubilados"], explain: "El grupo es mixto."),
                            Exercise(id: "es-read-grupo-caminata-q4", kind: "choice", prompt: "¿Qué hacen al final los que quieren?", options: ["Desayunan juntos", "Corren al río", "Vuelven a casa", "Toman el autobús"], answers: ["Desayunan juntos"], explain: "Desayunan juntos en un bar del mercado."),
                            Exercise(id: "es-read-grupo-caminata-q5", kind: "written", prompt: "¿Cuánto tiempo lleva Marta?", options: [], answers: ["un mes", "1 mes"], explain: "Marta va desde hace un mes.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "es-read-piso-luz", languageID: "es", title: "El anuncio del piso", level: "A2", topic: "pisos", unitID: "es-foundations-u7",
        text: "Piso luminoso de dos habitaciones en alquiler desde septiembre. Está en la tercera planta, con ascensor, y tiene un balcón que da al patio, así que es tranquilo. El salón es más grande que la cocina, pero la cocina tiene ventana. El barrio tiene mercado los sábados y la parada del metro está a cinco minutos. No es el más barato de la zona, pero es el mejor iluminado. Se pide un mes de fianza y se prefiere a alguien que trabaje desde casa, como los dueños actuales.",
        questions: [
                            Exercise(id: "es-read-piso-luz-q1", kind: "choice", prompt: "¿Cuándo está disponible?", options: ["Desde septiembre", "Desde agosto", "Ahora mismo", "En enero"], answers: ["Desde septiembre"], explain: "En alquiler desde septiembre."),
                            Exercise(id: "es-read-piso-luz-q2", kind: "choice", prompt: "¿Por qué es tranquilo?", options: ["Da al patio", "Está en la planta baja", "No tiene vecinos", "Está en el campo"], answers: ["Da al patio"], explain: "El balcón da al patio, así que es tranquilo."),
                            Exercise(id: "es-read-piso-luz-q3", kind: "written", prompt: "¿A cuántos minutos está el metro?", options: [], answers: ["cinco minutos", "5 minutos", "cinco"], explain: "La parada del metro está a cinco minutos."),
                            Exercise(id: "es-read-piso-luz-q4", kind: "choice", prompt: "¿Cómo es comparado con la zona?", options: ["No es el más barato, pero sí el mejor iluminado", "Es el más barato", "Es el peor iluminado", "Es el más pequeño"], answers: ["No es el más barato, pero sí el mejor iluminado"], explain: "No es el más barato de la zona, pero es el mejor iluminado."),
                            Exercise(id: "es-read-piso-luz-q5", kind: "choice", prompt: "¿A quién prefieren los dueños?", options: ["A alguien que trabaje desde casa", "A estudiantes", "A familias con niños", "A jubilados"], answers: ["A alguien que trabaje desde casa"], explain: "Se prefiere a alguien que trabaje desde casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "fr-read-groupe-marche", languageID: "fr", title: "Le groupe de marche", level: "A1", topic: "santé", unitID: "fr-foundations-u2",
        text: "Les mardis, le quartier organise une marche gratuite. Elle commence à neuf heures sur la place et finit au bord du fleuve. Le groupe est mixte : il y a des étudiants, des familles et des retraités. Personne ne court ; l'idée, c'est marcher et parler. À la fin, ceux qui veulent prennent le petit-déjeuner ensemble dans un bar du marché. Camille y va depuis un mois et elle a déjà trois nouveaux amis. Elle dit que c'est le moment le plus tranquille de sa semaine.",
        questions: [
                            Exercise(id: "fr-read-groupe-marche-q1", kind: "choice", prompt: "Quand a lieu la marche ?", options: ["Les mardis", "Les lundis", "Les samedis", "Tous les jours"], answers: ["Les mardis"], explain: "Les mardis, le quartier organise une marche gratuite."),
                            Exercise(id: "fr-read-groupe-marche-q2", kind: "written", prompt: "À quelle heure commence-t-elle ?", options: [], answers: ["a neuf heures", "à neuf heures", "neuf heures"], explain: "Elle commence à neuf heures sur la place."),
                            Exercise(id: "fr-read-groupe-marche-q3", kind: "choice", prompt: "Qui participe ?", options: ["Étudiants, familles et retraités", "Seulement des étudiants", "Seulement des retraités", "Seulement des familles"], answers: ["Étudiants, familles et retraités"], explain: "Le groupe est mixte."),
                            Exercise(id: "fr-read-groupe-marche-q4", kind: "choice", prompt: "Que font ceux qui veulent à la fin ?", options: ["Ils prennent le petit-déjeuner ensemble", "Ils courent au fleuve", "Ils rentrent chez eux", "Ils prennent le bus"], answers: ["Ils prennent le petit-déjeuner ensemble"], explain: "Petit-déjeuner ensemble dans un bar du marché."),
                            Exercise(id: "fr-read-groupe-marche-q5", kind: "written", prompt: "Depuis combien de temps Camille y va-t-elle ?", options: [], answers: ["un mois", "1 mois"], explain: "Camille y va depuis un mois.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "fr-read-annonce-appart", languageID: "fr", title: "L'annonce de l'appartement", level: "A2", topic: "appartements", unitID: "fr-foundations-u4",
        text: "Appartement lumineux de deux chambres à louer à partir de septembre. Il est au troisième étage, avec ascenseur, et il a un balcon qui donne sur la cour, donc il est calme. Le salon est plus grand que la cuisine, mais la cuisine a une fenêtre. Le quartier a un marché le samedi et la station de métro est à cinq minutes. Ce n'est pas le moins cher du quartier, mais c'est le mieux éclairé. Un mois de caution est demandé, et on préfère quelqu'un qui travaille à la maison, comme les propriétaires actuels.",
        questions: [
                            Exercise(id: "fr-read-annonce-appart-q1", kind: "choice", prompt: "Quand est-il disponible ?", options: ["À partir de septembre", "À partir d'août", "Tout de suite", "En janvier"], answers: ["À partir de septembre"], explain: "À louer à partir de septembre."),
                            Exercise(id: "fr-read-annonce-appart-q2", kind: "choice", prompt: "Pourquoi est-il calme ?", options: ["Il donne sur la cour", "Il est au rez-de-chaussée", "Il n'a pas de voisins", "Il est à la campagne"], answers: ["Il donne sur la cour"], explain: "Le balcon donne sur la cour, donc il est calme."),
                            Exercise(id: "fr-read-annonce-appart-q3", kind: "written", prompt: "À combien de minutes est le métro ?", options: [], answers: ["cinq minutes", "5 minutes", "cinq"], explain: "La station de métro est à cinq minutes."),
                            Exercise(id: "fr-read-annonce-appart-q4", kind: "choice", prompt: "Comment est-il comparé au quartier ?", options: ["Pas le moins cher, mais le mieux éclairé", "Le moins cher", "Le moins éclairé", "Le plus petit"], answers: ["Pas le moins cher, mais le mieux éclairé"], explain: "Pas le moins cher, mais le mieux éclairé."),
                            Exercise(id: "fr-read-annonce-appart-q5", kind: "choice", prompt: "Qui préfèrent les propriétaires ?", options: ["Quelqu'un qui travaille à la maison", "Des étudiants", "Des familles avec enfants", "Des retraités"], answers: ["Quelqu'un qui travaille à la maison"], explain: "On préfère quelqu'un qui travaille à la maison.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "it-read-gruppo-camminata", languageID: "it", title: "Il gruppo di camminata", level: "A1", topic: "salute", unitID: "it-foundations-u2",
        text: "Il martedì, il quartiere organizza una camminata gratis. Parte alle nove dalla piazza e arriva fino al fiume. Il gruppo è misto: ci sono studenti, famiglie e pensionati. Nessuno corre; l'idea è camminare e parlare. Alla fine, chi vuole fa colazione insieme in un bar del mercato. Giulia ci va da un mese e ha già tre amici nuovi. Dice che è il momento più tranquillo della sua settimana.",
        questions: [
                            Exercise(id: "it-read-gruppo-camminata-q1", kind: "choice", prompt: "Quando c'è la camminata ?", options: ["Il martedì", "Il lunedì", "Il sabato", "Tutti i giorni"], answers: ["Il martedì"], explain: "Il martedì, il quartiere organizza una camminata gratis."),
                            Exercise(id: "it-read-gruppo-camminata-q2", kind: "written", prompt: "A che ora parte ?", options: [], answers: ["alle nove", "le nove", "nove"], explain: "Parte alle nove dalla piazza."),
                            Exercise(id: "it-read-gruppo-camminata-q3", kind: "choice", prompt: "Chi partecipa ?", options: ["Studenti, famiglie e pensionati", "Solo studenti", "Solo pensionati", "Solo famiglie"], answers: ["Studenti, famiglie e pensionati"], explain: "Il gruppo è misto."),
                            Exercise(id: "it-read-gruppo-camminata-q4", kind: "choice", prompt: "Cosa fa chi vuole alla fine ?", options: ["Fa colazione insieme", "Corre al fiume", "Torna a casa", "Prende l'autobus"], answers: ["Fa colazione insieme"], explain: "Fa colazione insieme in un bar del mercato."),
                            Exercise(id: "it-read-gruppo-camminata-q5", kind: "written", prompt: "Da quanto tempo ci va Giulia ?", options: [], answers: ["un mese", "1 mese"], explain: "Giulia ci va da un mese.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "it-read-annuncio-appartamento", languageID: "it", title: "L'annuncio dell'appartamento", level: "A2", topic: "appartamenti", unitID: "it-foundations-u4",
        text: "Appartamento luminoso di due camere in affitto da settembre. È al terzo piano, con ascensore, e ha un balcone che dà sul cortile, quindi è tranquillo. Il salotto è più grande della cucina, ma la cucina ha la finestra. Il quartiere ha il mercato il sabato e la fermata della metro è a cinque minuti. Non è il meno costoso della zona, ma è il migliore illuminato. Si chiede un mese di caparra e si preferisce qualcuno che lavori da casa, come gli attuali proprietari.",
        questions: [
                            Exercise(id: "it-read-annuncio-appartamento-q1", kind: "choice", prompt: "Quando è disponibile ?", options: ["Da settembre", "Da agosto", "Subito", "A gennaio"], answers: ["Da settembre"], explain: "In affitto da settembre."),
                            Exercise(id: "it-read-annuncio-appartamento-q2", kind: "choice", prompt: "Perché è tranquillo ?", options: ["Dà sul cortile", "È al piano terra", "Non ha vicini", "È in campagna"], answers: ["Dà sul cortile"], explain: "Il balcone dà sul cortile, quindi è tranquillo."),
                            Exercise(id: "it-read-annuncio-appartamento-q3", kind: "written", prompt: "A quanti minuti c'è la metro ?", options: [], answers: ["cinque minuti", "5 minuti", "cinque"], explain: "La fermata della metro è a cinque minuti."),
                            Exercise(id: "it-read-annuncio-appartamento-q4", kind: "choice", prompt: "Com'è rispetto alla zona ?", options: ["Non il meno costoso, ma il migliore illuminato", "Il meno costoso", "Il meno illuminato", "Il più piccolo"], answers: ["Non il meno costoso, ma il migliore illuminato"], explain: "Non è il meno costoso, ma è il migliore illuminato."),
                            Exercise(id: "it-read-annuncio-appartamento-q5", kind: "choice", prompt: "Chi preferiscono i proprietari ?", options: ["Qualcuno che lavori da casa", "Studenti", "Famiglie con bambini", "Pensionati"], answers: ["Qualcuno che lavori da casa"], explain: "Si preferisce qualcuno che lavori da casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "pt-read-grupo-caminhada", languageID: "pt", title: "O grupo de caminhada", level: "A1", topic: "saúde", unitID: "pt-foundations-u2",
        text: "Às terças, o bairro organiza uma caminhada grátis. Começa às nove na praça e termina no rio. O grupo é misto: tem estudantes, famílias e aposentados. Ninguém corre; a ideia é caminhar e conversar. No fim, quem quiser toma café da manhã junto num bar da feira. Bia participa faz um mês e já tem três amigos novos. Ela diz que é a hora mais tranquila da semana dela.",
        questions: [
                            Exercise(id: "pt-read-grupo-caminhada-q1", kind: "choice", prompt: "Quando é a caminhada ?", options: ["Às terças", "Às segundas", "Aos sábados", "Todos os dias"], answers: ["Às terças"], explain: "Às terças, o bairro organiza uma caminhada grátis."),
                            Exercise(id: "pt-read-grupo-caminhada-q2", kind: "written", prompt: "A que horas começa ?", options: [], answers: ["as nove", "às nove", "nove horas"], explain: "Começa às nove na praça."),
                            Exercise(id: "pt-read-grupo-caminhada-q3", kind: "choice", prompt: "Quem participa ?", options: ["Estudantes, famílias e aposentados", "Só estudantes", "Só aposentados", "Só famílias"], answers: ["Estudantes, famílias e aposentados"], explain: "O grupo é misto."),
                            Exercise(id: "pt-read-grupo-caminhada-q4", kind: "choice", prompt: "O que faz quem quiser no fim ?", options: ["Toma café da manhã junto", "Corre até o rio", "Volta para casa", "Pega o ônibus"], answers: ["Toma café da manhã junto"], explain: "Toma café da manhã junto num bar da feira."),
                            Exercise(id: "pt-read-grupo-caminhada-q5", kind: "written", prompt: "Há quanto tempo a Bia participa ?", options: [], answers: ["um mes", "um mês", "1 mês", "1 mes"], explain: "A Bia participa faz um mês.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "pt-read-anuncio-apartamento", languageID: "pt", title: "O anúncio do apartamento", level: "A2", topic: "apartamentos", unitID: "pt-foundations-u4",
        text: "Apartamento claro de dois quartos para alugar a partir de setembro. Fica no terceiro andar, com elevador, e tem uma varanda para o pátio, então é tranquilo. A sala é maior que a cozinha, mas a cozinha tem janela. O bairro tem feira aos sábados e a estação de metrô fica a cinco minutos. Não é o mais barato da região, mas é o melhor iluminado. Pedem um mês de caução e preferem alguém que trabalhe de casa, como os atuais donos.",
        questions: [
                            Exercise(id: "pt-read-anuncio-apartamento-q1", kind: "choice", prompt: "Quando está disponível ?", options: ["A partir de setembro", "A partir de agosto", "Agora", "Em janeiro"], answers: ["A partir de setembro"], explain: "Para alugar a partir de setembro."),
                            Exercise(id: "pt-read-anuncio-apartamento-q2", kind: "choice", prompt: "Por que é tranquilo ?", options: ["Varanda para o pátio", "Fica no térreo", "Não tem vizinhos", "Fica no campo"], answers: ["Varanda para o pátio"], explain: "A varanda dá para o pátio, então é tranquilo."),
                            Exercise(id: "pt-read-anuncio-apartamento-q3", kind: "written", prompt: "A quantos minutos fica o metrô ?", options: [], answers: ["cinco minutos", "5 minutos", "cinco"], explain: "A estação de metrô fica a cinco minutos."),
                            Exercise(id: "pt-read-anuncio-apartamento-q4", kind: "choice", prompt: "Como é comparado com a região ?", options: ["Não é o mais barato, mas é o melhor iluminado", "É o mais barato", "É o pior iluminado", "É o menor"], answers: ["Não é o mais barato, mas é o melhor iluminado"], explain: "Não é o mais barato, mas é o melhor iluminado."),
                            Exercise(id: "pt-read-anuncio-apartamento-q5", kind: "choice", prompt: "Quem os donos preferem ?", options: ["Alguém que trabalhe de casa", "Estudantes", "Famílias com crianças", "Aposentados"], answers: ["Alguém que trabalhe de casa"], explain: "Preferem alguém que trabalhe de casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"])
    ]
}
